package com.vahotel.web;
import com.vahotel.model.*;import com.vahotel.repo.*;import jakarta.servlet.http.HttpServletResponse;import java.io.IOException;import java.nio.file.*;import java.math.BigDecimal;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ManagementController {private final AccountRepository accounts;private final RoomRepository rooms;private final ReservationRepository reservations;private final PaymentRecordRepository payments;private final CustomerReportRepository reports;private final org.springframework.security.crypto.password.PasswordEncoder encoder;private final com.vahotel.service.ReservationService reservationService;private final com.vahotel.service.PaymentService paymentService;
 public ManagementController(AccountRepository a,RoomRepository r,ReservationRepository b,PaymentRecordRepository p,CustomerReportRepository c,org.springframework.security.crypto.password.PasswordEncoder e,com.vahotel.service.ReservationService rs,com.vahotel.service.PaymentService ps){accounts=a;rooms=r;reservations=b;payments=p;reports=c;encoder=e;reservationService=rs;paymentService=ps;}
 @GetMapping({"/super-admin/dashboard","/online-manager/dashboard","/onsite-manager/dashboard"}) public String dashboard(Model m){m.addAttribute("pendingCustomers",accounts.findAll().stream().filter(a->a.getRole()==Role.CUSTOMER&&!a.isEnabled()).count());m.addAttribute("pendingReservations",reservations.findAll().stream().filter(r->"PENDING".equals(r.getStatus())||"PAID".equals(r.getStatus())||"CANCELLATION_REQUESTED".equals(r.getStatus())).count());return "management";}
 @GetMapping("/management/customers") public String customers(Model m){m.addAttribute("accounts",accounts.findAll());return "customers";}
 @PostMapping("/management/customers/{id}/approve") public String approve(@PathVariable Long id){Account a=accounts.findById(id).orElseThrow();a.setEnabled(true);accounts.save(a);return "redirect:/management/customers";}
 @PostMapping("/management/customers/{id}/reject") public String reject(@PathVariable Long id){accounts.deleteById(id);return "redirect:/management/customers";}
 @GetMapping("/management/customers/{id}/identity") public ResponseEntity<Resource> identity(@PathVariable Long id){Account a=accounts.findById(id).orElseThrow();if(a.getIdentityDocumentPath()==null)return ResponseEntity.notFound().build();Path p=Path.of(a.getIdentityDocumentPath()).toAbsolutePath().normalize();if(!Files.exists(p))return ResponseEntity.notFound().build();Resource res=new FileSystemResource(p);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=identity-"+id).body(res);}
 @GetMapping("/management/rooms") public String roomList(Model m){m.addAttribute("rooms",rooms.findAll());return "manage-rooms";}
 @PostMapping("/management/rooms") public String addRoom(@RequestParam String roomNumber,@RequestParam String roomType,@RequestParam String description,@RequestParam BigDecimal nightlyPrice,RedirectAttributes f){if(nightlyPrice.signum()<=0){f.addFlashAttribute("error","Nightly price must be positive.");return "redirect:/management/rooms";}rooms.save(new Room(roomNumber,roomType,description,nightlyPrice));return "redirect:/management/rooms";}
 @PostMapping("/management/rooms/{id}/update") public String updateRoom(@PathVariable Long id,@RequestParam String description,@RequestParam BigDecimal nightlyPrice,RedirectAttributes f){if(nightlyPrice.signum()<=0){f.addFlashAttribute("error","Nightly price must be positive.");return "redirect:/management/rooms";}Room room=rooms.findById(id).orElseThrow();room.setDescription(description);room.setNightlyPrice(nightlyPrice);rooms.save(room);return "redirect:/management/rooms";}
 @PostMapping("/management/rooms/{id}/toggle") public String toggle(@PathVariable Long id){Room r=rooms.findById(id).orElseThrow();r.setActive(!r.isActive());rooms.save(r);return "redirect:/management/rooms";}
 @GetMapping("/management/reservations") public String reservationList(Model m){m.addAttribute("reservations",reservations.findAll());return "manage-reservations";}
 @PostMapping("/management/reservations/{id}/{decision}") public String decide(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();if("cancel".equals(decision)&&!"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","There is no pending cancellation request for this reservation.");return "redirect:/management/reservations";}if("reject".equals(decision)&&"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","Choose Keep reservation or Confirm cancellation for a cancellation request.");return "redirect:/management/reservations";}if("approve".equals(decision)&&!"PAID".equals(r.getStatus())&&!"PENDING".equals(r.getStatus())&&!"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","Only fully paid reservations can be approved.");return "redirect:/management/reservations";}if(decision.equals("approve")){if("CANCELLATION_REQUESTED".equals(r.getStatus())){String restore=r.getStatusBeforeCancellation()==null?"APPROVED":r.getStatusBeforeCancellation();if(!r.getCheckIn().isAfter(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila"))))restore="EXPIRED";r.setStatus(restore);r.setStatusBeforeCancellation(null);}else{if(!r.getCheckIn().isAfter(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")))){f.addFlashAttribute("error","The reservation has expired because check-in has arrived.");return "redirect:/management/reservations";}r.setStatus("APPROVED");}}else if(decision.equals("reject"))r.setStatus("REJECTED");else if(decision.equals("cancel")){r.setStatus("CANCELLED");r.setStatusBeforeCancellation(null);}reservations.save(r);return "redirect:/management/reservations";}
 @GetMapping("/management/payments") public String paymentList(Model m){m.addAttribute("payments",payments.findAll());return "payments";}
 @GetMapping("/management/reports.csv") public void csv(HttpServletResponse res)throws IOException{res.setContentType("text/csv");res.setHeader("Content-Disposition","attachment; filename=va-hotel-reservations.csv");var w=res.getWriter();w.println("Reservation ID,Status,Check In,Check Out,Total Price,Amount Paid");for(Reservation r:reservations.findAll())w.printf("%d,%s,%s,%s,%s,%s%n",r.getId(),r.getStatus(),r.getCheckIn(),r.getCheckOut(),r.getTotalPrice(),r.getAmountPaid());}

 @GetMapping("/management/managers") public String managers(Model m){m.addAttribute("accounts",accounts.findAll().stream().filter(a->a.getRole()==Role.ONLINE_MANAGER||a.getRole()==Role.ONSITE_MANAGER).toList());return "managers";}
 @PostMapping("/management/managers") public String createManager(@RequestParam String fullName,@RequestParam String email,@RequestParam String role,@RequestParam String password,RedirectAttributes f){try{Role r=Role.valueOf(role);if(r!=Role.ONLINE_MANAGER&&r!=Role.ONSITE_MANAGER)throw new IllegalArgumentException("Invalid manager role.");if(accounts.findByEmail(email.trim().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already exists.");if(password.length()<12)throw new IllegalArgumentException("Manager password must be at least 12 characters.");accounts.save(new Account(email.trim().toLowerCase(),encoder.encode(password),fullName.trim(),r,true));}catch(Exception e){f.addFlashAttribute("error",e.getMessage()==null?"Invalid manager details.":e.getMessage());}return "redirect:/management/managers";}
 @PostMapping("/management/managers/{id}/disable") public String disableManager(@PathVariable Long id){Account a=accounts.findById(id).orElseThrow();if(a.getRole()==Role.ONLINE_MANAGER||a.getRole()==Role.ONSITE_MANAGER){a.setEnabled(false);accounts.save(a);}return "redirect:/management/managers";}
 @GetMapping("/management/walkins") public String walkins(Model m){m.addAttribute("rooms",rooms.findByActiveTrue());return "walkins";}
 @PostMapping("/management/walkins") public String createWalkin(@RequestParam String guestName,@RequestParam String guestEmail,@RequestParam Long roomId,@RequestParam java.time.LocalDate checkIn,@RequestParam java.time.LocalDate checkOut,@RequestParam String paymentMethod,RedirectAttributes f){try{String email=guestEmail.trim().toLowerCase();Account guest=accounts.findByEmail(email).orElseGet(()->accounts.save(new Account(email,encoder.encode(java.util.UUID.randomUUID().toString()),guestName.trim(),Role.CUSTOMER,true)));if(guest.getRole()!=Role.CUSTOMER)throw new IllegalArgumentException("That email belongs to a staff account.");Room room=rooms.findById(roomId).orElseThrow();Reservation booking=reservationService.create(guest,room,checkIn,checkOut);paymentService.simulateWalkInPayment(booking.getId(),booking.getTotalPrice(),paymentMethod);booking.setStatus("APPROVED");reservations.save(booking);f.addFlashAttribute("message","Walk-in reservation created and full payment recorded as a simulation. No money was transferred.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/management/walkins";}
 @GetMapping("/management/reports") public String reports(Model m){m.addAttribute("reports",reports.findAll());return "manager-reports";}
 @PostMapping("/management/reports/{id}/reply") public String reply(@PathVariable Long id,@RequestParam String reply){CustomerReport report=reports.findById(id).orElseThrow();report.setManagerReply(reply);report.setStatus("RESOLVED");reports.save(report);return "redirect:/management/reports";}
 @GetMapping("/management/history") public String history(Model m){m.addAttribute("reservations",reservations.findAll());return "reservation-history-manager";}


 @PostMapping("/management/payments/{id}/refund") public String refund(@PathVariable Long id,@RequestParam BigDecimal amount,RedirectAttributes f){try{paymentService.simulateRefund(id,amount);f.addFlashAttribute("message","Refund simulation recorded. No real money was transferred.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/management/payments";}
 @GetMapping("/management/revenue.csv") public void revenueCsv(HttpServletResponse res)throws IOException{res.setContentType("text/csv");res.setHeader("Content-Disposition","attachment; filename=va-hotel-revenue-records.csv");var w=res.getWriter();w.println("Payment ID,Reservation ID,Amount,Method,Status,Created At");for(PaymentRecord p:payments.findAll())w.printf("%d,%d,%s,%s,%s,%s%n",p.getId(),p.getReservation().getId(),p.getAmount(),p.getMethod(),p.getStatus(),p.getCreatedAt());}

 @GetMapping("/management/special-requests") public String specialRequests(Model m){m.addAttribute("reservations",reservations.findAll().stream().filter(x->x.getRequestedCheckOut()!=null||x.getRequestedUpgradeRoomId()!=null||x.isEarlyCheckoutRequested()||"PENCIL".equals(x.getBookingType())).toList());return "special-requests";}
 @PostMapping("/management/reservations/{id}/extension/{decision}") public String extension(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();if(r.getRequestedCheckOut()==null){f.addFlashAttribute("error","No extension request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){long extraNights=java.time.temporal.ChronoUnit.DAYS.between(r.getCheckOut(),r.getRequestedCheckOut());BigDecimal extra=r.getRoom().getNightlyPrice().multiply(BigDecimal.valueOf(extraNights));r.setCheckOut(r.getRequestedCheckOut());r.setRequestedCheckOut(null);f.addFlashAttribute("message","Extension approved. Additional amount ₱"+extra+" must be collected separately.");}else r.setRequestedCheckOut(null);reservations.save(r);return "redirect:/management/special-requests";}
 @PostMapping("/management/reservations/{id}/early-checkout/{decision}") public String earlyCheckoutDecision(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();if(!r.isEarlyCheckoutRequested()){f.addFlashAttribute("error","No early checkout request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){r.setStatus("CHECKED_OUT");r.setCheckedOutAt(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")));}r.setEarlyCheckoutRequested(false);reservations.save(r);return "redirect:/management/special-requests";}
 @PostMapping("/management/reservations/{id}/upgrade/{decision}") public String upgradeDecision(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();Long targetId=r.getRequestedUpgradeRoomId();if(targetId==null){f.addFlashAttribute("error","No upgrade request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){Room target=rooms.findById(targetId).orElseThrow();if(!target.isActive()||reservations.countOverlaps(target,r.getCheckIn(),r.getCheckOut())>0){f.addFlashAttribute("error","Requested room is no longer available.");return "redirect:/management/special-requests";}long nights=java.time.temporal.ChronoUnit.DAYS.between(r.getCheckIn(),r.getCheckOut());BigDecimal revised=target.getNightlyPrice().multiply(BigDecimal.valueOf(nights));r.setRoom(target);r.setTotalPrice(revised);f.addFlashAttribute("message","Upgrade approved. Review the revised balance before collecting additional payment.");}r.setRequestedUpgradeRoomId(null);reservations.save(r);return "redirect:/management/special-requests";}



 @PostMapping("/management/reservations/{id}/checkin") public String completeCheckin(@PathVariable Long id,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();java.time.LocalDate today=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila"));if(!"APPROVED".equals(r.getStatus())||!r.getCheckIn().equals(today)){f.addFlashAttribute("error","Check-in is allowed only for an approved reservation on its scheduled arrival date.");return "redirect:/management/history";}r.setCheckedInAt(today);r.setStatus("CHECKED_IN");reservations.save(r);f.addFlashAttribute("message","Guest checked in successfully.");return "redirect:/management/history";}
 @PostMapping("/management/reservations/{id}/checkout") public String completeCheckout(@PathVariable Long id,RedirectAttributes f){Reservation r=reservations.findById(id).orElseThrow();if(!"CHECKED_IN".equals(r.getStatus())){f.addFlashAttribute("error","Only checked-in guests can complete checkout.");return "redirect:/management/history";}r.setStatus("CHECKED_OUT");r.setCheckedOutAt(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")));reservations.save(r);f.addFlashAttribute("message","Checkout completed.");return "redirect:/management/history";}

}
